            print(f"ERROR: {path}: {e}")

def sample_list(root, limit=20):
    print("\nSample entries (up to {}):".format(limit))
    shown = 0
    try:
        with os.scandir(root) as it:
            for entry in it:
                try:
                    st = os.lstat(entry.path)
                    mode = stat.filemode(st.st_mode)
                    print(f"{mode} {entry.path}")
                except Exception as e:
                    print(f"ERR  {entry.path}: {e}")
                shown += 1
                if shown >= limit:
                    break
    except Exception as e:
        print(f"Could not list samples for {root}: {e}")

def main():
    if not os.path.isdir(TARGET):
        print(f"Directory not found: {TARGET}")
        return 1

    print(f"Starting recursive permission update to 0777 under: {TARGET}")
    start = time.time()
    counters = {'dirs': 0, 'files': 0, 'symlinks': 0, 'others': 0, 'errors': 0, 'processed': 0}

    # Ensure the root itself is accessible first
    safe_chmod(TARGET, 0o777, counters)

    for dirpath, dirnames, filenames in os.walk(TARGET, topdown=True, followlinks=False):
        safe_chmod(dirpath, 0o777, counters)
        counters['processed'] += 1

        for d in dirnames:
            dp = os.path.join(dirpath, d)
            safe_chmod(dp, 0o777, counters)
            counters['processed'] += 1

        for f in filenames:
            fp = os.path.join(dirpath, f)
            safe_chmod(fp, 0o777, counters)
            counters['processed'] += 1

        if counters['processed'] % 5000 == 0:
            elapsed = time.time() - start
            print(f"...processed {counters['processed']} entries in {elapsed:.1f}s; dirs={counters['dirs']} files={counters['files']} errors={counters['errors']}")

    elapsed = time.time() - start
    print("\nCompleted.")
    print(f"Summary: dirs={counters['dirs']}, files={counters['files']}, symlinks_skipped={counters['symlinks']}, others_skipped={counters['others']}, errors={counters['errors']}, elapsed={elapsed:.2f}s")

    sample_list(TARGET, limit=20)
    return 0

rc = main()
